 export type PortRange = [number, number];
+
+const ITEM = /^(\d+)\s*(?:-\s*(\d+))?$/;
+
+function parsePort(text: string, item: string): number {
+  const n = Number(text);
+  if (!Number.isSafeInteger(n) || n < 1 || n > 65535) {
+    throw new Error(`port out of range 1-65535 in "${item}"`);
+  }
+  return n;
+}

 /** Parse a port list into merged, sorted ranges. See README.md for the rules. */
 export function parsePorts(list: string): PortRange[] {
-  throw new Error("not implemented");
+  if (list.trim() === "") return [];
+
+  const ranges: PortRange[] = [];
+  for (const raw of list.split(",")) {
+    const item = raw.trim();
+    const match = ITEM.exec(item);
+    if (!match) {
+      throw new Error(`malformed port list item "${item}" in "${list}"`);
+    }
+    const from = parsePort(match[1], item);
+    const to = match[2] === undefined ? from : parsePort(match[2], item);
+    if (to < from) {
+      throw new Error(`range end below start in "${item}"`);
+    }
+    ranges.push([from, to]);
+  }
+
+  ranges.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
+
+  const merged: PortRange[] = [];
+  for (const [from, to] of ranges) {
+    const last = merged[merged.length - 1];
+    if (last && from <= last[1] + 1) {
+      last[1] = Math.max(last[1], to);
+    } else {
+      merged.push([from, to]);
+    }
+  }
+  return merged;
 }

